@pytest.fixture(params=["iPhone 15", "Pixel 7", "Galaxy S9+", "iPad (gen 7)"], ids=lambda d: d)
def mobile_page(request, playwright, browser, base_url, storage_state):
    descriptor = playwright.devices[request.param]
    context = browser.new_context(**descriptor, base_url=base_url, storage_state=storage_state)
    page = context.new_page()
    yield page
    context.close()


def test_no_horizontal_scrolling(mobile_page):
    App(mobile_page).products.open()

    overflow = mobile_page.evaluate(
        "() => document.documentElement.scrollWidth - document.documentElement.clientWidth"
    )

    assert overflow <= 1, f"Page scrolls horizontally by {overflow}px on this device"


def test_touch_targets_meet_the_minimum_size(mobile_page):
    products = App(mobile_page).products.open()
    if mobile_page.viewport_size["width"] > 640:
        pytest.skip("Desktop-width layout - touch sizing does not apply")

    box = products.page.locator("[data-testid=menu-toggle]").bounding_box()

    assert box["width"] >= 44 and box["height"] >= 44, f"Touch target is {box}"

